// SPDX-License-Identifier: MIT
pragma solidity 0.8.35;

/// @notice Fail-closed probe for Ethereum BLS12-381 precompile `0x0b`.
/// @dev CoNET today returns empty success, which is not a pairing.
///      Base reverts or returns data. A settler must not be installed while
///      `available()` is false.
contract AacEthereumBlsProbe {
    address private constant G1_ADD = 0x000000000000000000000000000000000000000b;

    function available() external view returns (bool) {
        (bool ok, bytes memory data) = G1_ADD.staticcall("");
        if (ok && data.length == 0) return false;
        return ok || data.length > 0;
    }
}
